        .arg(Arg::new("version").short('v').long("version").help("Show program's version number and exit").action(ArgAction::SetTrue))
        .arg(Arg::new("errors-only").long("errors-only").help("Only show validation errors").action(ArgAction::SetTrue))
        .arg(Arg::new("connect-timeout").long("connect-timeout").value_name("SECONDS").help("Timeout for establishing connections (in seconds)"))
        .arg(Arg::new("timeout").long("timeout").value_name("SECONDS").help("Total timeout for HTTP requests (in seconds)"))
