                    // For {"exclusiveMinimum": true} in 2020, with no instance? Actually that schema with instance gave "Schema is invalid. Error: true is not of type \"number\""
                    // So meta error for exclusiveMinimum boolean.
                    // Implement:
                    if let Some(Value::Bool(_)) = map.get("exclusiveMinimum") {
                        // In new drafts, exclusiveMinimum must be number, so bool is invalid.
                        // Message: "true is not of type \"number\""
                        // Which value? The exclusiveMinimum value itself.
                        if let Some(v) = map.get("exclusiveMinimum") {
                            return Some(format!("{} is not of type \"number\"", v.to_string()));
                        }
                    }
                    if let Some(Value::Bool(_)) = map.get("exclusiveMaximum") {
                        if let Some(v) = map.get("exclusiveMaximum") {
                            return Some(format!("{} is not of type \"number\"", v.to_string()));
                        }
                    }
                    // dependentRequired vs dependencies? In old drafts, dependentRequired should be ignored? But meta error? Actually schema {"dependentRequired": ...} in draft 4 with valid instance gave VALID (ignored), not meta error. So no meta error.
