                        let cloned = resolved.clone();
                        self.validate_inner(&cloned, instance, errors, inst_path, schema_path, eval_path);
                        return;
                    } else {
                        // Should have been caught in build, but if not, ignore?
                        return;
                    }
                }
                // Validate each keyword
                // Order? Need canonical order. For now, use fixed order that matches observed for common:
                // type, enum, const, multipleOf, minimum, maximum, exclusiveMinimum, exclusiveMaximum, minLength, maxLength, pattern, format, minItems, maxItems, uniqueItems, items, prefixItems, contains, minProperties, maxProperties, required, properties, patternProperties, additionalProperties, propertyNames, allOf, anyOf, oneOf, not, if/then/else, dependentRequired, dependencies, etc.
                // We'll implement in that order.
                self.check_type(map, instance, errors);
                self.check_enum(map, instance, errors);
                self.check_const(map, instance, errors);
                self.check_numbers(map, instance, errors);
                self.check_strings(map, instance, errors);
                self.check_array(map, instance, errors);
                self.check_object(map, instance, errors);
                self.check_combinators(map, instance, errors, inst_path, schema_path, eval_path);
                // if/then/else handled in combinators
            },
            _ => {}
        }
    }

    // ... implement each check ...
}
