fn resolve_pointer<'a>(doc: &'a Value, pointer: &str) -> Option<&'a Value> {
    if pointer.is_empty() { return Some(doc); }
    if !pointer.starts_with('/') { return None; }
    let mut cur = doc;
    for part in pointer[1..].split('/') {
        let key = part.replace("~1", "/").replace("~0", "~");
        match cur {
            Value::Object(m) => cur = m.get(&key)?,
            Value::Array(a) => {
                let idx: usize = key.parse().ok()?;
                cur = a.get(idx)?;
            },
            _ => return None,
        }
    }
    Some(cur)
}

fn escape_pointer(s: &str) -> String {
    s.replace("~", "~0").replace("/", "~1")
}

impl ValidationContext {
    fn resolve_ref(&mut self, ref_str: &str) -> Option<Value> {
        // Internal
        if ref_str.starts_with('#') {
            let frag = &ref_str[1..];
            if frag.is_empty() {
                return Some(self.root_schema.clone());
            }
            // frag like "/$defs/foo" or "/properties/a"
            // Need to handle percent decoding? For simplicity, direct.
            if let Some(v) = resolve_pointer(&self.root_schema, frag) {
                return Some(v.clone());
            } else {
                return None;
            }
        }
