    fn is_type(&self, type_name: &str, instance: &Value) -> bool {
        match type_name {
            "string" => instance.is_string(),
            "integer" => {
                match instance {
                    Value::Number(n) => {
                        if n.is_i64() || n.is_u64() { true }
                        else if n.is_f64() {
                            if self.draft == Draft::D4 {
                                false
                            } else {
                                let f = n.as_f64().unwrap();
                                f.fract() == 0.0 && f.is_finite()
                            }
                        } else { false }
                    },
                    _ => false,
                }
            },
            "number" => instance.is_number(),
            "boolean" => instance.is_boolean(),
            "object" => instance.is_object(),
            "array" => instance.is_array(),
            "null" => instance.is_null(),
            _ => false,
        }
    }

    fn check_type(&self, map: &serde_json::Map<String, Value>, instance: &Value, errors: &mut Vec<String>) {
        if let Some(t) = map.get("type") {
            match t {
                Value::String(s) => {
                    if !self.is_type(s, instance) {
                        errors.push(format!("{} is not of type {:?}", instance.to_string(), s));
                        // Note: format is `42 is not of type "string"` with quotes. Using {:?} gives quoted string.
                    }
                },
                Value::Array(arr) => {
                    let mut ok = false;
                    for v in arr {
                        if let Value::String(s) = v {
                            if self.is_type(s, instance) { ok = true; break; }
                        }
                    }
                    if !ok {
                        // What message for type array failure? Probably similar but with list? Let's check: schema {"type": ["string","integer"]} with 1.5? What message?
                        // For now, use generic: `X is not of type "string", "integer"`? Need to test.
                        // Let's generate: `X is not of types ...`? Actually meta error for invalid type uses "is not of types". For instance validation with type array failure, what message?
                        // Test needed. For now, use same as single but with first? Better to check original.
                        // We'll produce: `X is not of type "string", "integer"`? Hmm.
                        // Let's just produce first type's message? Or generic.
                        // To be safe, we'll produce message listing all: e.g., `1.5 is not of type "string", "integer"`? Need to verify.
                        // For now, fallback to: `X is not of types ...`? Let's use simple.
                        let types: Vec<String> = arr.iter().filter_map(|v| if let Value::String(s)=v { Some(format!("{:?}", s)) } else { None }).collect();
                        if types.len() == 1 {
                            errors.push(format!("{} is not of type {}", instance.to_string(), types[0]));
                        } else {
                            errors.push(format!("{} is not of types {}", instance.to_string(), types.join(", ")));
                        }
                    }
                },
                _ => {}
            }
        }
    }

    fn check_enum_const(&self, map: &serde_json::Map<String, Value>, instance: &Value, errors: &mut Vec<String>) {
        if let Some(e) = map.get("enum") {
            if let Value::Array(arr) = e {
                let mut found = false;
                for v in arr {
                    if v == instance { found = true; break; }
                }
                if !found {
                    if arr.len() == 1 {
                        errors.push(format!("{} is not one of {}", instance.to_string(), arr[0].to_string()));
                    } else if arr.len() == 2 {
                        errors.push(format!("{} is not one of {} or {}", instance.to_string(), arr[0].to_string(), arr[1].to_string()));
                    } else if arr.len() > 2 {
                        let mut parts: Vec<String> = arr[..arr.len()-1].iter().map(|v| v.to_string()).collect();
                        let last = arr[arr.len()-1].to_string();
                        errors.push(format!("{} is not one of {} or {}", instance.to_string(), parts.join(", "), last));
                    }
                }
            }
        }
        if let Some(c) = map.get("const") {
            if c != instance {
                errors.push(format!("{} was expected", c.to_string()));
            }
        }
    }

    fn check_numbers(&self, map: &serde_json::Map<String, Value>, instance: &Value, errors: &mut Vec<String>) {
        let num = match instance {
            Value::Number(n) => n.as_f64(),
            _ => None,
        };
        if num.is_none() { return; }
        let f = num.unwrap();
        if let Some(Value::Number(m)) = map.get("minimum") {
            if let Some(mf) = m.as_f64() {
                if f < mf {
                    errors.push(format!("{} is less than the minimum of {}", instance.to_string(), m.to_string()));
                }
            }
        }
        if let Some(Value::Number(m)) = map.get("maximum") {
            if let Some(mf) = m.as_f64() {
                if f > mf {
                    errors.push(format!("{} is greater than the maximum of {}", instance.to_string(), m.to_string()));
                }
            }
        }
        // exclusiveMinimum/Maximum handling draft-aware
        match self.draft {
            Draft::D4 => {
                // exclusiveMinimum boolean + minimum
                if let Some(Value::Bool(true)) = map.get("exclusiveMinimum") {
                    if let Some(Value::Number(m)) = map.get("minimum") {
                        if let Some(mf) = m.as_f64() {
                            if f <= mf {
                                errors.push(format!("{} is less than or equal to the minimum of {}", instance.to_string(), m.to_string()));
                            }
                        }
                    }
                }
                if let Some(Value::Bool(true)) = map.get("exclusiveMaximum") {
                    if let Some(Value::Number(m)) = map.get("maximum") {
                        if let Some(mf) = m.as_f64() {
                            if f >= mf {
                                errors.push(format!("{} is greater than or equal to the maximum of {}", instance.to_string(), m.to_string()));
                            }
                        }
                    }
                }
            },
            _ => {
                if let Some(v) = map.get("exclusiveMinimum") {
                    if let Some(ef) = v.as_f64() {
                        if f <= ef {
                            errors.push(format!("{} is less than or equal to the minimum of {}", instance.to_string(), v.to_string()));
                        }
                    }
                }
                if let Some(v) = map.get("exclusiveMaximum") {
                    if let Some(ef) = v.as_f64() {
                        if f >= ef {
                            errors.push(format!("{} is greater than or equal to the maximum of {}", instance.to_string(), v.to_string()));
                        }
                    }
                }
                // Also need to handle minimum/maximum alongside exclusive? Already handled separately. For schema {"minimum":5,"exclusiveMinimum":10} with 7, error was "7 is less than or equal to minimum of 10" (only exclusive, not minimum). Our code will produce both? For 7, minimum 5 passes (7>=5), exclusive 10 fails (7<=10) => one error correct. For 3, both fail? Would produce two errors: "3 is less than minimum of 5" and "3 is less than or equal to minimum of 10". What does original do? Need to test.
            }
        }
        if let Some(Value::Number(m)) = map.get("multipleOf") {
            if let Some(mf) = m.as_f64() {
                if mf != 0.0 {
                    // Check multiple: f / mf should be integer (with floating tolerance)
                    let q = f / mf;
                    // Use tolerance for floating point
                    if (q - q.round()).abs() > 1e-9 {
                        errors.push(format!("{} is not a multiple of {}", instance.to_string(), m.to_string()));
                    }
                }
            }
        }
    }

