            for k in obj.keys() {
                if evaluated.contains(k) { continue; }
                match uneval {
                    Value::Bool(false) => {
                        errors.push(format!("Unevaluated properties are not allowed ('{}' was unexpected)", k));
                        break;
                    },
                    Value::Bool(true) => {},
                    _ => {
                        if let Some(v) = obj.get(k) {
                            let mut sub_err = vec![];
                            self.validate_inner(uneval, v, &mut sub_err);
                            errors.extend(sub_err);
                        }
                    }
