    fn check_combinators(&mut self, map: &serde_json::Map<String, Value>, instance: &Value, errors: &mut Vec<String>) {
        if let Some(Value::Array(arr)) = map.get("allOf") {
            for sub in arr {
                let mut sub_err = vec![];
                self.validate_inner(sub, instance, &mut sub_err);
                errors.extend(sub_err);
            }
        }
        if let Some(Value::Array(arr)) = map.get("anyOf") {
            let mut any_valid = false;
            for sub in arr {
                let mut sub_err = vec![];
                self.validate_inner(sub, instance, &mut sub_err);
                if sub_err.is_empty() { any_valid = true; break; }
            }
            if !any_valid {
                errors.push(format!("{} is not valid under any of the schemas listed in the 'anyOf' keyword", instance.to_string()));
            }
        }
        if let Some(Value::Array(arr)) = map.get("oneOf") {
            let mut count = 0;
            for sub in arr {
                let mut sub_err = vec![];
                self.validate_inner(sub, instance, &mut sub_err);
                if sub_err.is_empty() { count += 1; }
            }
            if count != 1 {
                errors.push(format!("{} is not valid under any of the schemas listed in the 'oneOf' keyword", instance.to_string()));
                // Note: original for oneOf with 0 matches gives "is not valid under any...", but with 2+ matches, what message? Probably "is valid under each of..."? Need to test.
