            }
        }
        if let Some(not_schema) = map.get("not") {
            if not_schema.is_object() || not_schema.is_boolean() {
                let mut sub_err = vec![];
                self.validate_inner(not_schema, instance, &mut sub_err);
                if sub_err.is_empty() {
                    errors.push(format!("{} is not allowed for {}", not_schema.to_string(), instance.to_string()));
                }
            }
        }
        // if/then/else
        if map.contains_key("if") {
            let if_schema = &map["if"];
            let mut if_err = vec![];
            self.validate_inner(if_schema, instance, &mut if_err);
            let cond = if_err.is_empty();
            if cond {
                if let Some(then_schema) = map.get("then") {
                    let mut sub_err = vec![];
                    self.validate_inner(then_schema, instance, &mut sub_err);
                    errors.extend(sub_err);
                }
            } else {
                if let Some(else_schema) = map.get("else") {
                    let mut sub_err = vec![];
                    self.validate_inner(else_schema, instance, &mut sub_err);
                    errors.extend(sub_err);
                }
            }
        }
    }

